from functools import singledispatch

@singledispatch
def describe(x):
    return f"object: {x!r}"

@describe.register
def _(x: int):
    return f"int with {x.bit_length()} bits"

@describe.register
def _(x: str):
    return f"text of {len(x)} chars"

print(describe("hello"))
print(describe(255))

from functools import singledispatch

@singledispatch
def describe(x):
    return f"object: {x!r}"

@describe.register
def _(x: int):
    return f"int with {x.bit_length()} bits"

@describe.register(bool)
def _(x):
    return "flag on" if x else "flag off"

print(describe(True))
print(describe(False))
print(describe(7))
